import json
def transform(g):
    g=[r[:] for r in g]
    h=len(g); w=len(g[0])
    rows=[i for i in range(h) if any(x==5 for x in g[i])]
    cols=[j for j in range(w) if any(g[i][j]==5 for i in range(h))]
    r0,r1,c0,c1=min(rows),max(rows),min(cols),max(cols)
    marks={}
    for i in range(h):
        for j in range(w):
            v=g[i][j]
            if v not in (0,5): marks[v]=(i,j)
    ri0,ri1,cj0,cj1=r0+1,r1-1,c0+1,c1-1
    rm=(ri0+ri1+1)//2; cm=(cj0+cj1+1)//2
    quads={'TL':(ri0,rm,cj0,cm),'TR':(ri0,rm,cm,cj1+1),'BL':(rm,ri1+1,cj0,cm),'BR':(rm,ri1+1,cm,cj1+1)}
    opp={'TL':'BR','BR':'TL','TR':'BL','BL':'TR'}
    for v,(i,j) in marks.items():
        key=('T' if i<rm else 'B')+('L' if j<cm else 'R')
        for k in (key,opp[key]):
            a,b,c,d=quads[k]
            for x in range(a,b):
                for y in range(c,d): g[x][y]=v
    return g

